- 修复后的 bootstrap CI 应有 gold_empty 过滤 (CoNLL 3453→2756)

### N-scaling Bootstrap
- N=8 vs N=16 的 Δρ bootstrap CI (B=10000)

## 输出格式
整理为统一 JSON，保存到本地 artifacts/data/bootstrap_ci_summary.json:

```json
{
  "qwen_scierc_3seed": {
    "ner": {
      "SJ": {"seeds": [0.428, 0.424, 0.384], "mean": 0.412, "sd": 0.025, "cv_pct": 6.0},
      "FK": {...}, "EM": {...}, "voting_conf": {...}, "logprob": {...}
    }
  },
  "llama_conll_3seed": {
    "ner": {
      "SJ": {"seeds": [0.464, 0.470, 0.455], "mean": 0.463, "sd": 0.007, "cv_pct": 1.6},
      ...
    }
  },
  "bootstrap_ci": {
    "qwen_conll_nscaling": {
      "SJ": {"rho_n8": 0.439, "rho_n16": 0.450, "delta": 0.011, "ci_95": [-0.014, 0.035]},
      ...
    },
    "qwen_scierc_nscaling": {...},
    "llama_scierc_nscaling": {...}
  },
  "bootstrap_ci_single": {
    "qwen_scierc_ner": {
      "SJ": {"rho": 0.398, "ci_95": [0.295, 0.459]},
